class Solution:
    def strongPasswordCheckerII(self, password: str) -> bool:
        if len(password) < 8:
            return False
        sp = set('!@#$%^&*()-+')
        low = up = dig = spe = False
        for i, ch in enumerate(password):
            if ch.islower(): low = True
            if ch.isupper(): up = True
            if ch.isdigit(): dig = True
            if ch in sp: spe = True
            if i and password[i] == password[i-1]:
                return False
        return low and up and dig and spe

