class Solution {
public:
    bool strongPasswordCheckerII(string password) {
        if (password.size() < 8) return false;
        string sp = "!@#$%^&*()-+";
        bool low = false, up = false, dig = false, spe = false;
        for (int i = 0; i < password.size(); i++) {
            char c = password[i];
            if (islower(c)) low = true;
            if (isupper(c)) up = true;
            if (isdigit(c)) dig = true;
            if (sp.find(c) != string::npos) spe = true;
            if (i && password[i] == password[i-1]) return false;
        }
        return low && up && dig && spe;
    }
};

