class Solution {
    public boolean strongPasswordCheckerII(String password) {
        if (password.length() < 8) return false;
        String sp = "!@#$%^&*()-+";
        boolean low = false, up = false, dig = false, spe = false;
        for (int i = 0; i < password.length(); i++) {
            char c = password.charAt(i);
            if (Character.isLowerCase(c)) low = true;
            if (Character.isUpperCase(c)) up = true;
            if (Character.isDigit(c)) dig = true;
            if (sp.indexOf(c) >= 0) spe = true;
            if (i > 0 && password.charAt(i) == password.charAt(i - 1)) return false;
        }
        return low && up && dig && spe;
    }
}

