var strongPasswordCheckerII = function(password) {
    if (password.length < 8) return false;
    const sp = new Set('!@#$%^&*()-+');
    let low = false, up = false, dig = false, spe = false;
    for (let i = 0; i < password.length; i++) {
        const c = password[i];
        if (c >= 'a' && c <= 'z') low = true;
        if (c >= 'A' && c <= 'Z') up = true;
        if (c >= '0' && c <= '9') dig = true;
        if (sp.has(c)) spe = true;
        if (i > 0 && c === password[i - 1]) return false;
    }
    return low && up && dig && spe;
};
